test("c1: combined hours and minutes are turned into seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c2: a bare number with no unit is seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("c3: a decimal part is accepted", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("c4: upper-case unit letters are accepted", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("c5: units written smaller before larger return null", () => {
  assert.equal(parseDuration("30m1h"), null);
  // The stub returns null for everything, so also require the same parts in the right order to parse.
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c6: text with an unknown unit returns null", () => {
  assert.equal(parseDuration("1x"), null);
  // The stub returns null for everything, so also require the same number with a known unit to parse.
  assert.equal(parseDuration("1h"), 3600);
});

test('c1: "1h30m" returns 5400', () => {
  assert.equal(parseDuration('1h30m'), 5400);
});

test('c2: a bare number with no unit is returned as seconds', () => {
  assert.equal(parseDuration('90'), 90);
});

test('c3: a decimal part is accepted', () => {
  assert.equal(parseDuration('1.5h'), 5400);
});

test('c4: upper-case unit letters are accepted', () => {
  assert.equal(parseDuration('1H30M'), 5400);
});

test('c5: units written smaller before larger return null', () => {
  assert.equal(parseDuration('30m1h'), null);
  // The same units in larger-before-smaller order must parse, so a stub returning null does not pass.
  assert.equal(parseDuration('1h30m'), 5400);
});

test('c6: text with an unknown unit returns null', () => {
  assert.equal(parseDuration('1x'), null);
  // The same number with a known unit must parse, so a stub returning null does not pass.
  assert.equal(parseDuration('1h'), 3600);
});

test("c1: combined hours and minutes are summed in seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c2: a bare number is seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("c3: a part can be a decimal", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("c4: units can be upper case", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("c5: units written smaller before larger are null", () => {
  assert.equal(parseDuration("30m1h"), null);
  // The same parts in the right order parse, so the null above comes from the order.
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c6: an unknown unit is null", () => {
  assert.equal(parseDuration("1x"), null);
  // The same number with a known unit parses, so the null above comes from the unit.
  assert.equal(parseDuration("1h"), 3600);
});
